package paritystub

import (
	"strings"

	"github.com/gofiber/fiber/v2"

	"github.com/haaku-tv/haaku/internal/openapi"
)

// Stub registration guard (hand-written; everything else in this package is
// generated by scripts/parity-stubs.py).
//
// The generated routes already carry the /v1 prefix, so they must be mounted on
// the app root, not on the /v1 group. And a stub must never win against a real
// handler: a concrete stub naming a value of a real value-discriminator route
// (e.g. /v1/sync/collection/episodes under /v1/sync/collection/{type}) is
// skipped so the real handler keeps serving it. A numeric `{id}` route does not
// claim a stub: /v1/movies/{id} cannot serve "hot", so the stub stays and
// answers an honest 501.

// discriminatorParams are path parameters whose accepted values are a
// documented set the real handler dispatches on.
var discriminatorParams = map[string]bool{
	"type": true, "media_type": true, "period": true, "sort_by": true, "sort_how": true,
}

// newStubRouter wraps the root router so stub registrations are filtered
// against the routes real packages have already registered. Every package's
// openapi definitions exist by the time httpapi.RegisterRoutes runs.
func newStubRouter(api fiber.Router) fiber.Router {
	return stubRouter{Router: api, claimed: claimedByRealRoutes()}
}

// stubRouter filters stub registrations.
type stubRouter struct {
	fiber.Router
	claimed map[string]bool // "METHOD /concrete/path"
}

func (s stubRouter) Get(path string, h ...fiber.Handler) fiber.Router {
	return s.register("GET", path, s.Router.Get, h...)
}
func (s stubRouter) Post(path string, h ...fiber.Handler) fiber.Router {
	return s.register("POST", path, s.Router.Post, h...)
}
func (s stubRouter) Put(path string, h ...fiber.Handler) fiber.Router {
	return s.register("PUT", path, s.Router.Put, h...)
}
func (s stubRouter) Patch(path string, h ...fiber.Handler) fiber.Router {
	return s.register("PATCH", path, s.Router.Patch, h...)
}
func (s stubRouter) Delete(path string, h ...fiber.Handler) fiber.Router {
	return s.register("DELETE", path, s.Router.Delete, h...)
}

func (s stubRouter) register(method, path string, add func(string, ...fiber.Handler) fiber.Router, h ...fiber.Handler) fiber.Router {
	if s.claimed[method+" "+path] {
		return s
	}
	return add(path, h...)
}

// claimedByRealRoutes returns the concrete paths served by a real route whose
// wildcards are all value discriminators. Only concrete paths are claimed: a
// stub that is itself a pattern is left alone.
func claimedByRealRoutes() map[string]bool {
	routes := openapi.AllRoutes()
	claimed := map[string]bool{}
	for _, r := range routes {
		if _, isStub := r.StatusCodes[501]; isStub {
			continue
		}
		segs := pathSegments(r.Path)
		if !discriminatorPattern(segs) {
			continue
		}
		for _, other := range routes {
			if other.Method != r.Method {
				continue
			}
			osegs := pathSegments(other.Path)
			if len(osegs) != len(segs) {
				continue
			}
			match := true
			for i := range segs {
				if isPathParam(segs[i]) {
					if isPathParam(osegs[i]) {
						match = false // leave pattern stubs alone
						break
					}
					continue
				}
				if osegs[i] != segs[i] {
					match = false
					break
				}
			}
			if match {
				claimed[other.Method+" "+other.Path] = true
			}
		}
	}
	return claimed
}

func pathSegments(p string) []string {
	return strings.Split(strings.Trim(p, "/"), "/")
}

func isPathParam(seg string) bool {
	return (strings.HasPrefix(seg, "{") && strings.HasSuffix(seg, "}")) || strings.HasPrefix(seg, ":")
}

func paramName(seg string) string {
	if strings.HasPrefix(seg, ":") {
		return seg[1:]
	}
	return strings.Trim(seg, "{}")
}

// discriminatorPattern reports whether every wildcard in segs is a value
// discriminator (see discriminatorParams) and there is at least one.
func discriminatorPattern(segs []string) bool {
	found := false
	for _, seg := range segs {
		if !isPathParam(seg) {
			continue
		}
		if !discriminatorParams[paramName(seg)] {
			return false
		}
		found = true
	}
	return found
}
